#!/usr/bin/env python3
"""
Round 176b (culprits), 5 October 2026. Needs round 175b.

Coal mine parent companies ranked by methane (the lost round 146b).

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 176b (5 October)\n\nNeeds round 175b (guards on its heading). Tiles patch round176b_tiles.py\nbeside it. No app.js?v= bump. Carries the lost round 146b's coal work.\n\n- The owner's Global Energy Monitor download, packed into culprits-tiles-more\n  gem/coal/download/ (README there says what): the Global Coal Mine Tracker\n  (August 2026) as it came; the boundaries zip with only its all-mines\n  GeoJSON, spreadsheet and README (the 500 one-mine files repeat them); the\n  Global Energy Ownership Tracker's Coal Mine Ownership sheet as CSV.\n- tiles gem_coal.py: mines from every sheet with positions and mine IDs\n  (open 5,390 rows, closed 1,754; 7,139 placed, 5 without a position), each\n  saying its sheet; colour from GEM's own methane estimate, the reported\n  figure for closed mines. Each mine's box lists its distinct ownership\n  chains, one line each with the parent's headquarters (26,959 lines),\n  instead of every ownership row whole (the file went from 52 to 28 MB).\n- rank_parents: methane/gem_coal_parents.geojson (1,512 placed) and\n  gem_coal_parents.json (all 1,665): each parent's share of each mine's\n  methane, added up. A parent reached by several chains to one mine counts\n  once, at the largest share; an \"unknown\" share is not divided but shown\n  apart. GEM estimate and reported methane kept apart. Placed at the\n  headquarters country's capital (forest500_map.capitals); GEM_COUNTRY\n  maps Russia and Virgin Islands (British). Run on the real files in the\n  sandbox; 153 parents with no country (small shareholders, natural\n  persons, unknown, some companies) are ranked in the JSON, not placed.\n- Map: gem_coal_parents first under Methane > Culprits, coloured by\n  attributed methane (or methane at unknown-share mines, or mines held).\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round176b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 175b" not in h.read_text(encoding="utf-8"):
        sys.exit("round176b: round 175b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round176b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round176b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round176b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
